import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:3003';
const WS_URL = 'ws://localhost:3003';

interface BloodBag {
    BagID: number;
    DonorName: string;
    BloodType: string;
    CollectionDate: string;
    ExpiryDate: string;
}

interface Donor {
    DonorID: number;
    DonorName: string;
    BloodType: string;
}

const InventoryManagement = () => {
    const [inventory, setInventory] = useState<BloodBag[]>([]);
    const [donors, setDonors] = useState<Donor[]>([]);
    const [selectedDonor, setSelectedDonor] = useState<Donor | null>(null);
    const [quantity, setQuantity] = useState(1);
    const [expiryDate, setExpiryDate] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    const fetchInventory = async () => {
        try {
            const response = await axios.get(`${API_URL}/inventory`);
            setInventory(response.data);
        } catch (err) {
            console.error(err);
            setError('Failed to fetch inventory.');
        }
    };

    const fetchDonors = async () => {
        try {
            const response = await axios.get(`${API_URL}/donors`);
            setDonors(response.data);
        } catch (err) {
            console.error(err);
            setError('Failed to fetch donors.');
        }
    };

    useEffect(() => {
        fetchInventory();
        fetchDonors();
        const ws = new WebSocket(WS_URL);
        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            if (message.type === 'new_update') {
                fetchInventory();
                fetchDonors();
            }
        };
        return () => ws.close();
    }, []);

    const handleAddBag = async (e: React.FormEvent) => {
        e.preventDefault();
        e.preventDefault();
        setError(null);
        setSuccess(null);
        if (!selectedDonor || !expiryDate || quantity < 1) {
            setError('A donor, expiry date, and valid quantity are required.');
            return;
        }
        try {
            const { DonorID, BloodType } = selectedDonor;
            await axios.post(`${API_URL}/inventory`, {
                donorId: DonorID,
                bloodType: BloodType,
                expiryDate,
                quantity
            });
            setSuccess(`${quantity} blood bag(s) added successfully.`);
            // Reset form
            setSelectedDonor(null);
            setExpiryDate('');
            setQuantity(1);
        } catch (err) {
            setError('Failed to add blood bag(s).');
            console.error(err);
        }
    };

    const handleDeleteBag = async (bagId: number) => {
        try {
            await axios.delete(`${API_URL}/bags/${bagId}`);
            fetchInventory(); // Refresh the list
        } catch (err) {
            setError('Failed to delete blood bag.');
            console.error(err);
        }
    };

    return (
        <div className="blood-bank-container">
            <div className="form-container">
                <h2>Add New Blood Bag</h2>
                <form onSubmit={handleAddBag} className="request-form">
                    {error && <div className="alert error">{error}</div>}
                    {success && <div className="alert success">{success}</div>}
                    <div className="form-group">
                        <label>Select Donor</label>
                        <select
                            value={selectedDonor ? selectedDonor.DonorID : ''}
                            onChange={(e) => {
                                const donor = donors.find(d => d.DonorID === parseInt(e.target.value));
                                setSelectedDonor(donor || null);
                            }}
                        >
                            <option value="" disabled>-- Select a Donor --</option>
                            {donors.map(donor => (
                                <option key={donor.DonorID} value={donor.DonorID}>
                                    {donor.DonorName} ({donor.BloodType})
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="form-group">
                        <label>Expiry Date</label>
                        <input
                            type="date"
                            value={expiryDate}
                            onChange={(e) => setExpiryDate(e.target.value)}
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label>Quantity</label>
                        <input
                            type="number"
                            value={quantity}
                            onChange={(e) => setQuantity(parseInt(e.target.value, 10))}
                            min="1"
                            required
                        />
                    </div>
                    <button type="submit" className="submit-btn">Add to Inventory</button>
                </form>
            </div>
            <div className="inventory-list">
                <h2>Current Inventory</h2>
                <table className="requests-table">
                    <thead>
                        <tr>
                            <th>Bag ID</th>
                            <th>Donor Name</th>
                            <th>Blood Type</th>
                            <th>Collection Date</th>
                            <th>Expiry Date</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {inventory.map((bag) => (
                            <tr key={bag.BagID}>
                                <td>{bag.BagID}</td>
                                <td>{bag.DonorName || '_'}</td>
                                <td>{bag.BloodType}</td>
                                <td>{new Date(bag.CollectionDate).toLocaleDateString()}</td>
                                <td>{new Date(bag.ExpiryDate).toLocaleDateString()}</td>
                                <td>
                                    <button onClick={() => handleDeleteBag(bag.BagID)} className="delete-btn">
                                        Delete
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default InventoryManagement;
